mapper.select:
SELECT e.*, r.name AS room_name FROM cal_event e LEFT JOIN cal_meeting_room r ON r.id = e.room_id
WHERE 1 = 1
AND e.end_time >= #{start}
AND e.start_time <= #{end}
ORDER BY e.start_time

SELECT COUNT(*) FROM cal_event WHERE room_id = #{roomId}
AND start_time < #{end} AND end_time > #{start}
AND id != #{excludeId}
